/*Table structure for table `auth_user` */

DROP TABLE IF EXISTS `auth_user`;

CREATE TABLE `auth_user` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `password` varchar(128) NOT NULL,
  `last_login` datetime(6) DEFAULT NULL,
  `is_superuser` tinyint(1) NOT NULL,
  `username` varchar(150) DEFAULT NULL,
  `first_name` varchar(150) NOT NULL,
  `last_name` varchar(150) NOT NULL,
  `birth_date` date DEFAULT NULL,
  `usr_email` varchar(254) DEFAULT NULL,
  `usr_profile_pic` varchar(100) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL,
  `is_verify` tinyint(1) NOT NULL,
  `is_notification` tinyint(1) NOT NULL,
  `is_message` tinyint(1) NOT NULL,
  `is_staff` tinyint(1) NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `date_joined` datetime(6) NOT NULL,
  `email_verified_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `added_by_id` bigint NOT NULL,
  `blood_group` varchar(3) DEFAULT NULL,
  `campus_code` varchar(150) DEFAULT NULL,
  `card_name` varchar(150) DEFAULT NULL,
  `gender` varchar(6) DEFAULT NULL,
  `student_code` varchar(150) DEFAULT NULL,
  `usr_department` varchar(150) DEFAULT NULL,
  `usr_designation` varchar(150) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `usr_email` (`usr_email`),
  KEY `auth_user_added_by_id_6f940683_fk_auth_user_id` (`added_by_id`),
  CONSTRAINT `auth_user_added_by_id_6f940683_fk_auth_user_id` FOREIGN KEY (`added_by_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=229 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `auth_user` */

