/*Table structure for table `auth_user_addresses` */

DROP TABLE IF EXISTS `auth_user_addresses`;

CREATE TABLE `auth_user_addresses` (
  `user_id` bigint NOT NULL,
  `address_line_1` longtext NOT NULL,
  `address_line_2` longtext NOT NULL,
  `state` varchar(255) NOT NULL,
  `city` varchar(255) NOT NULL,
  `upazila` varchar(255) DEFAULT NULL,
  `area` varchar(255) DEFAULT NULL,
  `post_code` varchar(255) NOT NULL,
  `country` varchar(255) NOT NULL,
  PRIMARY KEY (`user_id`),
  CONSTRAINT `auth_user_addresses_user_id_04f87b71_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

