) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `campaign_areabasedreward` */

/*Table structure for table `campaign_areabasedreward_area` */

DROP TABLE IF EXISTS `campaign_areabasedreward_area`;

CREATE TABLE `campaign_areabasedreward_area` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `areabasedreward_id` bigint NOT NULL,
  `address_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `campaign_areabasedreward_areabasedreward_id_addre_9959a9b1_uniq` (`areabasedreward_id`,`address_id`),
  KEY `campaign_areabasedre_address_id_fa3d1405_fk_auth_user` (`address_id`),
  CONSTRAINT `campaign_areabasedre_address_id_fa3d1405_fk_auth_user` FOREIGN KEY (`address_id`) REFERENCES `auth_user_addresses` (`user_id`),
  CONSTRAINT `campaign_areabasedre_areabasedreward_id_85f0fe79_fk_campaign_` FOREIGN KEY (`areabasedreward_id`) REFERENCES `campaign_areabasedreward` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `campaign_areabasedreward_area` */

