/*Table structure for table `dma_card_bindings` */

DROP TABLE IF EXISTS `dma_card_bindings`;

CREATE TABLE `dma_card_bindings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `service_detail` json NOT NULL,
  `max_amount_per_day` int DEFAULT NULL,
  `max_amount_per_month` int DEFAULT NULL,
  `max_tx_per_day` int DEFAULT NULL,
  `max_tx_per_month` int DEFAULT NULL,
  `min_amount_per_tx` int DEFAULT NULL,
  `max_amount_per_tx` int DEFAULT NULL,
  `bkash_auth_code` varchar(255) DEFAULT NULL,
  `bkash_auth_state` varchar(255) DEFAULT NULL,
  `bkash_access_token` varchar(255) DEFAULT NULL,
  `shurjo_access_token` varchar(255) DEFAULT NULL,
  `status` longtext NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `card_id` bigint NOT NULL,
  `organization_merchant_id` bigint NOT NULL,
  `user_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dma_card_bindings_card_id_organization_merchant_id_e2aa6bdd_uniq` (`card_id`,`organization_merchant_id`),
  KEY `dma_card_bindings_organization_merchan_6252f729_fk_org_merch` (`organization_merchant_id`),
  KEY `dma_card_bindings_user_id_d8782682_fk_auth_user_id` (`user_id`),
  CONSTRAINT `dma_card_bindings_card_id_6353f5dd_fk_dma_cards_id` FOREIGN KEY (`card_id`) REFERENCES `dma_cards` (`id`),
  CONSTRAINT `dma_card_bindings_organization_merchan_6252f729_fk_org_merch` FOREIGN KEY (`organization_merchant_id`) REFERENCES `org_merchants` (`id`),
  CONSTRAINT `dma_card_bindings_user_id_d8782682_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `dma_card_bindings` */

insert  into `dma_card_bindings`(`id`,`service_detail`,`max_amount_per_day`,`max_amount_per_month`,`max_tx_per_day`,`max_tx_per_month`,`min_amount_per_tx`,`max_amount_per_tx`,`bkash_auth_code`,`bkash_auth_state`,`bkash_access_token`,`shurjo_access_token`,`status`,`created_at`,`updated_at`,`card_id`,`organization_merchant_id`,`user_id`) values (1,'{\"service_id\": \"1\", \"service_type\": \"PPS\"}',NULL,NULL,NULL,NULL,NULL,NULL,'Default20230620a2035ebfda6fbdee','663A8FA9-D836-48EE-8AA1-1FF682989DC7','Default2023062041562c2efaaeed8a',NULL,'ACTIVE','2023-06-20 17:40:52.692860','2023-06-20 17:40:52.692870',76,6,95);

/*Table structure for table `dma_card_requests` */

DROP TABLE IF EXISTS `dma_card_requests`;

CREATE TABLE `dma_card_requests` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `request_detail` json DEFAULT NULL,
  `courier_detail` longtext,
  `binding_detail` json DEFAULT NULL,
  `card_detail` json DEFAULT NULL,
  `status` longtext NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `requested_by_id` bigint DEFAULT NULL,
  `card_pickup_location` varchar(255) DEFAULT NULL,
  `type` longtext NOT NULL,
  `user_refer` longtext,
  PRIMARY KEY (`id`),
  KEY `dma_card_requests_requested_by_id_71f28f0f_fk_auth_user_id` (`requested_by_id`),
  CONSTRAINT `dma_card_requests_requested_by_id_71f28f0f_fk_auth_user_id` FOREIGN KEY (`requested_by_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=216 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

