/*Table structure for table `dma_card_service_requests` */

DROP TABLE IF EXISTS `dma_card_service_requests`;

CREATE TABLE `dma_card_service_requests` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `request_detail` json DEFAULT NULL,
  `binding_detail` json DEFAULT NULL,
  `status` longtext NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `card_id` bigint NOT NULL,
  `requested_by_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `dma_card_service_requests_card_id_722b1eda_fk_dma_cards_id` (`card_id`),
  KEY `dma_card_service_req_requested_by_id_f9199a62_fk_auth_user` (`requested_by_id`),
  CONSTRAINT `dma_card_service_req_requested_by_id_f9199a62_fk_auth_user` FOREIGN KEY (`requested_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `dma_card_service_requests_card_id_722b1eda_fk_dma_cards_id` FOREIGN KEY (`card_id`) REFERENCES `dma_cards` (`id`)
