/*Data for the table `dma_card_service_requests` */

/*Table structure for table `dma_cards` */

DROP TABLE IF EXISTS `dma_cards`;

CREATE TABLE `dma_cards` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `card_number` varchar(255) NOT NULL,
  `sku_number` varchar(255) NOT NULL,
  `cvc` int unsigned DEFAULT NULL,
  `activation_otp` int DEFAULT NULL,
  `activation_qr_code` varchar(100) DEFAULT NULL,
  `status` longtext NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `expires_at` datetime(6) DEFAULT NULL,
  `organization_id` bigint DEFAULT NULL,
  `user_id` bigint DEFAULT NULL,
  `encrypted_data` longtext,
  `phone_sku_number` varchar(255) DEFAULT NULL,
  `request_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `card_number` (`card_number`),
  UNIQUE KEY `sku_number` (`sku_number`),
  UNIQUE KEY `dma_cards_organization_id_user_id_62b20017_uniq` (`organization_id`,`user_id`),
  KEY `dma_cards_user_id_654537e5_fk_auth_user_id` (`user_id`),
  CONSTRAINT `dma_cards_organization_id_4941d95c_fk_organizations_id` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `dma_cards_user_id_654537e5_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `dma_cards_chk_1` CHECK ((`cvc` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=164 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

