/*Table structure for table `dma_cards_life_logs` */

DROP TABLE IF EXISTS `dma_cards_life_logs`;

CREATE TABLE `dma_cards_life_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `requested` json DEFAULT NULL,
  `prepared` json DEFAULT NULL,
  `allocated` json DEFAULT NULL,
  `printed` json DEFAULT NULL,
  `approved` json DEFAULT NULL,
  `cancelled` json DEFAULT NULL,
  `delivered` json DEFAULT NULL,
  `activated` json DEFAULT NULL,
  `returned` json DEFAULT NULL,
  `lost` json DEFAULT NULL,
  `destroyed` json DEFAULT NULL,
  `dumped` json DEFAULT NULL,
  `card_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `card_id` (`card_id`),
  CONSTRAINT `dma_cards_life_logs_card_id_a751e6a0_fk_dma_cards_id` FOREIGN KEY (`card_id`) REFERENCES `dma_cards` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `dma_cards_life_logs` */

/*Table structure for table `dmacard_rewards` */

DROP TABLE IF EXISTS `dmacard_rewards`;

CREATE TABLE `dmacard_rewards` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `reward_detail` json DEFAULT NULL,
  `total_earned` int NOT NULL,
  `reward_point` int NOT NULL,
  `total_redeemed` int NOT NULL,
  `total_consumed` int NOT NULL,
  `today_total_reward` int DEFAULT NULL,
  `is_applicable` tinyint(1) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `card_id` bigint NOT NULL,
  `organization_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dmaCard_rewards_card_id_organization_id_10b516e1_uniq` (`card_id`,`organization_id`),
  KEY `dmaCard_rewards_organization_id_d08cf4b3_fk_organizations_id` (`organization_id`),
  CONSTRAINT `dmaCard_rewards_card_id_60dbd3bb_fk_dma_cards_id` FOREIGN KEY (`card_id`) REFERENCES `dma_cards` (`id`),
  CONSTRAINT `dmaCard_rewards_organization_id_d08cf4b3_fk_organizations_id` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`)
