/*Table structure for table `notification_configuration` */

DROP TABLE IF EXISTS `notification_configuration`;

CREATE TABLE `notification_configuration` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `con_code` varchar(50) DEFAULT NULL,
  `con_message_title` varchar(300) DEFAULT NULL,
  `con_message_body` longtext,
  `con_created_at` datetime(6) NOT NULL,
  `con_updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `notification_configuration` */

/*Table structure for table `notification_notifications` */

