/*Table structure for table `office_branch_devices` */

DROP TABLE IF EXISTS `office_branch_devices`;

CREATE TABLE `office_branch_devices` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `location_check` tinyint(1) NOT NULL,
  `configuration` json DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `added_by_id` bigint DEFAULT NULL,
  `branch_id` bigint NOT NULL,
  `device_id` bigint NOT NULL,
  `door_lock_gateway_id` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `device_id` (`device_id`),
  UNIQUE KEY `office_branch_devices_branch_id_device_id_d20e2b21_uniq` (`branch_id`,`device_id`),
  KEY `office_branch_devices_added_by_id_2e42124d_fk_auth_user_id` (`added_by_id`),
  CONSTRAINT `office_branch_devices_added_by_id_2e42124d_fk_auth_user_id` FOREIGN KEY (`added_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `office_branch_devices_branch_id_67e52019_fk_office_branches_id` FOREIGN KEY (`branch_id`) REFERENCES `office_branches` (`id`),
  CONSTRAINT `office_branch_devices_device_id_323f6dbb_fk_pos_devices_id` FOREIGN KEY (`device_id`) REFERENCES `pos_devices` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

