/*Table structure for table `transaction_refund` */

DROP TABLE IF EXISTS `transaction_refund`;

CREATE TABLE `transaction_refund` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `refund_request_id` varchar(255) DEFAULT NULL,
  `refund_id` varchar(255) DEFAULT NULL,
  `is_refunded` tinyint(1) NOT NULL,
  `refund_response` json DEFAULT NULL,
  `refunded_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `transaction_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_id` (`transaction_id`),
  UNIQUE KEY `refund_request_id` (`refund_request_id`),
  UNIQUE KEY `refund_id` (`refund_id`),
  CONSTRAINT `transaction_refund_transaction_id_048fc182_fk_transactions_id` FOREIGN KEY (`transaction_id`) REFERENCES `transactions` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `transaction_refund` */

/*Table structure for table `transactions` */

DROP TABLE IF EXISTS `transactions`;

CREATE TABLE `transactions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `service_detail` json DEFAULT NULL,
  `type` int NOT NULL,
  `transaction_id` varchar(255) DEFAULT NULL,
  `payment_id` varchar(255) DEFAULT NULL,
  `capture_id` varchar(255) DEFAULT NULL,
  `payment_request_id` varchar(255) DEFAULT NULL,
  `capture_request_id` varchar(255) DEFAULT NULL,
  `amount` decimal(19,2) NOT NULL,
  `payable_amount` decimal(19,2) NOT NULL,
  `payment_response` json DEFAULT NULL,
  `is_paid` tinyint(1) NOT NULL,
  `is_cancelled` tinyint(1) NOT NULL,
  `purpose` longtext,
  `authorized_at` datetime(6) DEFAULT NULL,
  `cancelled_at` datetime(6) DEFAULT NULL,
  `captured_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `collected_by_id` bigint DEFAULT NULL,
  `paid_by_id` bigint NOT NULL,
  `payment_service_id` bigint DEFAULT NULL,
  `payment_mode` longtext NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_id` (`transaction_id`),
  UNIQUE KEY `payment_id` (`payment_id`),
  UNIQUE KEY `capture_id` (`capture_id`),
  UNIQUE KEY `payment_request_id` (`payment_request_id`),
  UNIQUE KEY `capture_request_id` (`capture_request_id`),
  KEY `transactions_collected_by_id_dbacd836_fk_auth_user_id` (`collected_by_id`),
  KEY `transactions_paid_by_id_70cb0f51_fk_auth_user_id` (`paid_by_id`),
  KEY `transactions_payment_service_id_87c70557_fk_payment_services_id` (`payment_service_id`),
  CONSTRAINT `transactions_collected_by_id_dbacd836_fk_auth_user_id` FOREIGN KEY (`collected_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `transactions_paid_by_id_70cb0f51_fk_auth_user_id` FOREIGN KEY (`paid_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `transactions_payment_service_id_87c70557_fk_payment_services_id` FOREIGN KEY (`payment_service_id`) REFERENCES `payment_services` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1541 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

