/*Table structure for table `users_fcm` */

DROP TABLE IF EXISTS `users_fcm`;

CREATE TABLE `users_fcm` (
  `user_id` bigint NOT NULL,
  `token` longtext,
  PRIMARY KEY (`user_id`),
  CONSTRAINT `users_fcm_user_id_fc4e4c2b_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `users_fcm` */

/*Table structure for table `users_location` */

DROP TABLE IF EXISTS `users_location`;

CREATE TABLE `users_location` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `loc_lat` varchar(200) DEFAULT NULL,
  `loc_long` varchar(200) DEFAULT NULL,
  `user_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `users_location_user_id_3bae858a_fk_auth_user_id` (`user_id`),
  CONSTRAINT `users_location_user_id_3bae858a_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `users_location` */

/*Table structure for table `users_phone` */

DROP TABLE IF EXISTS `users_phone`;

CREATE TABLE `users_phone` (
  `user_id` bigint NOT NULL,
  `phn_business` varchar(50) DEFAULT NULL,
  `phn_cell` varchar(50) NOT NULL,
  `phn_home` varchar(50) DEFAULT NULL,
  `verified_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `users_phone_phn_cell_c4bc1618_uniq` (`phn_cell`),
  CONSTRAINT `users_phone_user_id_d19565e2_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
