/*Table structure for table `vehicles` */

DROP TABLE IF EXISTS `vehicles`;

CREATE TABLE `vehicles` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `reg_number` varchar(255) NOT NULL,
  `num_of_axle` int DEFAULT NULL,
  `manufacturer` varchar(255) DEFAULT NULL,
  `model` varchar(255) DEFAULT NULL,
  `chassis_no` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `owner_id` bigint NOT NULL,
  `type_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reg_number` (`reg_number`),
  UNIQUE KEY `owner_id` (`owner_id`),
  KEY `vehicles_type_id_03e8e2c1_fk_vehicles_vehicletype_id` (`type_id`),
  CONSTRAINT `vehicles_owner_id_8cbe0576_fk_auth_user_id` FOREIGN KEY (`owner_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `vehicles_type_id_03e8e2c1_fk_vehicles_vehicletype_id` FOREIGN KEY (`type_id`) REFERENCES `vehicles_vehicletype` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `vehicles` */

/*Table structure for table `vehicles_vehicledocument` */

