  `file` varchar(100) DEFAULT NULL,
  `document_type` varchar(1050) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `vehicle_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `vehicles_vehicledocument_vehicle_id_e848f6f9_fk_vehicles_id` (`vehicle_id`),
